function normalize(value = '') {
  return String(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/https?:\/\/\S+/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined || value === '') return [];
  return [value];
}

function validUrls(value) {
  return asArray(value)
    .map((item) => String(item).trim())
    .filter((item) => /^https?:\/\//i.test(item));
}

function readTable(nodeName, headerAlternatives) {
  let rawRows = [];

  try {
    rawRows = $(nodeName)
      .all()
      .map((item) => item.json || {});
  } catch {
    return [];
  }

  if (!rawRows.length) return [];

  for (const headers of headerAlternatives) {
    const firstRowHasHeaders = headers.every((header) =>
      Object.prototype.hasOwnProperty.call(rawRows[0], header)
    );

    if (firstRowHasHeaders) {
      return rawRows;
    }

    const headerRowIndex = rawRows.findIndex((row) => {
      const values = Object.values(row).map((value) =>
        String(value ?? '').trim()
      );

      return headers.every((header) => values.includes(header));
    });

    if (headerRowIndex < 0) continue;

    const headerRow = rawRows[headerRowIndex];
    const columnKeys = Object.keys(headerRow).filter(
      (key) => key !== 'row_number'
    );

    const columnNames = columnKeys.map((key) =>
      String(headerRow[key] ?? '').trim()
    );

    return rawRows
      .slice(headerRowIndex + 1)
      .map((row) => {
        const result = {};

        columnKeys.forEach((key, index) => {
          const columnName = columnNames[index];

          if (columnName) {
            result[columnName] = row[key];
          }
        });

        return result;
      })
      .filter((row) =>
        Object.values(row).some(
          (value) => String(value ?? '').trim() !== ''
        )
      );
  }

  return rawRows;
}

function parseGeminiResponse(rawValue) {
  if (rawValue && typeof rawValue === 'object') {
    if (Array.isArray(rawValue.posts)) return rawValue.posts;
    if (Array.isArray(rawValue)) return rawValue;
  }

  let text = String(rawValue ?? '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    const parsed = JSON.parse(text);

    if (Array.isArray(parsed)) return parsed;
    if (Array.isArray(parsed.posts)) return parsed.posts;
  } catch {
    // Spróbujemy wydobyć sam JSON z odpowiedzi.
  }

  const objectStart = text.indexOf('{');
  const objectEnd = text.lastIndexOf('}');

  if (objectStart >= 0 && objectEnd > objectStart) {
    const parsed = JSON.parse(text.slice(objectStart, objectEnd + 1));

    if (Array.isArray(parsed)) return parsed;
    if (Array.isArray(parsed.posts)) return parsed.posts;
  }

  const arrayStart = text.indexOf('[');
  const arrayEnd = text.lastIndexOf(']');

  if (arrayStart >= 0 && arrayEnd > arrayStart) {
    const parsed = JSON.parse(text.slice(arrayStart, arrayEnd + 1));

    if (Array.isArray(parsed)) return parsed;
  }

  throw new Error('Odpowiedź Gemini nie zawiera tablicy posts.');
}

const response = $input.first().json || {};

const responseText =
  (response.candidates?.[0]?.content?.parts || [])
    .map((part) => String(part.text || ''))
    .join('') ||
  response.output ||
  response.text ||
  response.content ||
  '';

let posts = [];

try {
  posts = parseGeminiResponse(responseText);
} catch (error) {
  return [
    {
      json: {
        skipWrite: true,
        workflowStatus: 'GEMINI_PARSE_ERROR',
        content:
          '⚠️ Social Ninja: Gemini zwrócił odpowiedź, której nie udało się przetworzyć.\n' +
          String(error.message || error),
        raw_response: responseText.slice(0, 1800),
      },
    },
  ];
}

const existingRows = readTable('GS — Existing QUEUE', [
  ['Item_ID', 'Created_At', 'Content_Type', 'Topic', 'Status'],
]);

let driveRows = [];

try {
  driveRows = $('Drive — Recent briefs/assets')
    .all()
    .map((item) => item.json || {});
} catch {
  driveRows = [];
}

const assets = driveRows
  .map((file) => {
    const id = String(file.id || file.fileId || '');
    const name = String(file.name || file.fileName || '');
    const mimeType = String(file.mimeType || file.mime_type || '');

    return {
      id,
      name,
      normalizedName: normalize(name),
      mimeType,
      url: String(
        file.webViewLink ||
          file.webContentLink ||
          file.url ||
          (id ? `https://drive.google.com/file/d/${id}/view` : '')
      ),
    };
  })
  .filter((asset) => {
    const mimeOk = /^(image|video|audio)\//i.test(asset.mimeType);
    const extensionOk = /\.(mp4|mov|m4v|jpg|jpeg|png|webp|gif|wav|mp3)$/i.test(asset.name);
    return asset.id && asset.mimeType !== 'application/vnd.google-apps.folder' && (mimeOk || extensionOk);
  });

const historyCutoff = Date.now() - 45 * 24 * 60 * 60 * 1000;

const existingKeys = new Set(
  existingRows
    .filter((row) => {
      const createdAt = new Date(row.Created_At || 0).getTime();

      return Number.isFinite(createdAt) && createdAt >= historyCutoff;
    })
    .map(
      (row) =>
        `${normalize(row.Topic)}|${String(
          row.Content_Type || ''
        ).toUpperCase()}`
    )
);

const allowedTypes = new Set([
  'REEL',
  'POST',
  'CAROUSEL',
  'STORY',
]);

const allowedChannels = new Set([
  'INSTAGRAM',
  'FACEBOOK',
  'INSTAGRAM+FACEBOOK',
]);

const seenKeys = new Set();
const validPosts = [];

let reelCount = 0;

for (const rawPost of posts) {
  const post = rawPost || {};

  const contentType = String(post.content_type || '')
    .trim()
    .toUpperCase();

  const channels = String(
    post.channels || 'INSTAGRAM+FACEBOOK'
  )
    .trim()
    .toUpperCase();

  const topic = String(post.topic || '').trim();
  const hook = String(post.hook || '').trim();
  const caption = String(post.caption_pl || '').trim();

  if (!allowedTypes.has(contentType)) continue;
  if (!allowedChannels.has(channels)) continue;
  if (!topic || !hook || !caption) continue;

  if (contentType === 'REEL' && reelCount >= 2) {
    continue;
  }

  const sourceUrls = validUrls(post.source_urls);

  const requiredAssets = asArray(post.required_assets)
    .map((item) => String(item).trim())
    .filter(Boolean);

  let assetId = String(post.asset_drive_id || '').trim();
  let assetUrl = String(post.asset_url || '').trim();
  let assetName = String(post.asset_name || '').trim();

  if (!assetId && !assetUrl && assets.length) {
    const wantedText = normalize(
      [
        topic,
        hook,
        assetName,
        ...requiredAssets,
      ].join(' ')
    );

    const rankedAssets = assets
      .map((asset) => {
        const score = asset.normalizedName
          .split(' ')
          .filter(
            (token) =>
              token.length >= 3 &&
              wantedText.includes(token)
          ).length;

        return {
          asset,
          score,
        };
      })
      .sort((a, b) => b.score - a.score);

    if (rankedAssets[0]?.score > 0) {
      assetId = rankedAssets[0].asset.id;
      assetUrl = rankedAssets[0].asset.url;
      assetName = rankedAssets[0].asset.name;
    }
  }

  const selectedAsset = assets.find((asset) => asset.id === assetId || asset.url === assetUrl);
  if ((assetId || assetUrl) && !selectedAsset) {
    assetId = '';
    assetUrl = '';
    assetName = '';
  }

  const sourceType =
    assetId || assetUrl
      ? 'ASSET'
      : sourceUrls.length
        ? 'CURRENT'
        : 'EVERGREEN';

  const dedupeKey = `${normalize(topic)}|${contentType}`;

  if (!normalize(topic)) continue;
  if (seenKeys.has(dedupeKey)) continue;
  if (existingKeys.has(dedupeKey)) continue;

  seenKeys.add(dedupeKey);

  if (contentType === 'REEL') {
    reelCount += 1;
  }

  validPosts.push({
    ...post,
    content_type: contentType,
    channels,
    topic,
    hook,
    caption_pl: caption,
    source_type: sourceType,
    source_urls: sourceUrls,
    required_assets: requiredAssets,
    asset_name: assetName,
    asset_url: assetUrl,
    asset_drive_id: assetId,
  });
}

const sourcePriority = {
  CURRENT: 0,
  ASSET: 1,
  EVERGREEN: 2,
};

validPosts.sort(
  (a, b) =>
    (sourcePriority[a.source_type] ?? 9) -
    (sourcePriority[b.source_type] ?? 9)
);

const selectedPosts = validPosts.slice(0, 5);

const currentOrAssetCount = selectedPosts.filter(
  (post) =>
    post.source_type === 'CURRENT' ||
    post.source_type === 'ASSET'
).length;

if (
  selectedPosts.length < 3 ||
  currentOrAssetCount < 2
) {
  return [
    {
      json: {
        skipWrite: true,
        workflowStatus: 'NO_CONTENT',
        content:
          `ℹ️ **Social Ninja zakończył pracę bez zapisu do kolejki.**\n\n` +
          `Gemini zwrócił: ${posts.length}\n` +
          `Poprawne po walidacji: ${validPosts.length}\n` +
          `Wybrane: ${selectedPosts.length}\n` +
          `CURRENT/ASSET: ${currentOrAssetCount}\n` +
          `Pliki Drive: ${assets.length}`,
        diagnostics: {
          geminiPosts: posts.length,
          validPosts: validPosts.length,
          selectedPosts: selectedPosts.length,
          currentOrAsset: currentOrAssetCount,
          driveAssets: assets.length,
        },
      },
    },
  ];
}

const now = new Date();

const createdAt = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Europe/Warsaw',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
