      post.on_screen_text || ''
    ),

    Caption_PL: post.caption_pl,
    CTA: String(post.cta || ''),

    Hashtags: Array.isArray(post.hashtags)
      ? post.hashtags.join(' ')
      : String(post.hashtags || ''),

    Suggested_Publish_At: String(
      post.suggested_publish_at || ''
    ),

    Channels: post.channels,
    Status: 'READY_FOR_APPROVAL',

    Approval_Note:
      `Wygenerowane automatycznie; wymagana ręczna akceptacja. ` +
      `Źródło: ${post.source_type}.`,

    Published_At: '',
    IG_Media_ID: '',
